    92→      const navigationState: TabNavigationState = {
    93→        location,
    94→        breadcrumbStack: resolvedNavigation.breadcrumbStack,
    95→      };
    96→
    97→      if (options?.openInNewTab || !activeTabId) {
    98→        return openTab({
    99→          navigationState,
