   502→function buildLocationFromLegacyUrl(url: string): DesktopLocation {
   503→  const parsed = urlToLocation(url);
   504→  if (parsed) {
   505→    return parsed;
   506→  }
   507→
   508→  if (url === "/documents") {
   509→    return { kind: "documents" };
   510→  }
   511→  if (url === "/devices/pair") {
   512→    return { kind: "device-pair" };
   513→  }
   514→  if (url.startsWith("/settings")) {
   515→    const section = url.split("/")[2];
   516→    return { kind: "settings", section: normalizeSettingsSection(section) };
   517→  }
   518→
   519→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   520→    return { kind: "global-route", path: url };
   521→  }
   522→
   523→  if (url.startsWith("/workspace/page")) {
   524→    const parsed = new URL(url, "http://desktop.local");
   525→    const workspaceId = parsed.searchParams.get("workspace_id");
   526→    const pagePath = parsed.searchParams.get("page_path");
   527→    return {
   528→      kind: "workspace-page",
   529→      workspaceId: workspaceId ?? "global",
   530→      pageSlug:
   531→        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
   532→    };
   533→  }
   534→
   535→  if (url.startsWith("/workspace/")) {
   536→    const parsed = new URL(url, "http://desktop.local");
   537→    const parts = parsed.pathname.split("/").filter(Boolean);
   538→    const workspaceId = parts[1];
   539→    if (!workspaceId) {
   540→      return { kind: "documents" };
   541→    }
   542→
   543→    if (parts.length === 2) {
   544→      return { kind: "workspace-home", workspaceId };
   545→    }
   546→
   547→    if (parts[2] === "apps" && !parts[3]) {
   548→      return { kind: "workspace-apps", workspaceId };
   549→    }
   550→
   551→    if (parts[2] === "page" && parts[3]) {
   552→      return {
   553→        kind: "workspace-page",
   554→        workspaceId,
   555→        pageSlug: parts
   556→          .slice(3)
   557→          .map((part) => decodeURIComponent(part))
   558→          .join("/"),
   559→      };
   560→    }
   561→
   562→    if (parts[2] === "agent" && parts[3]) {
   563→      return {
   564→        kind: "workspace-agent-detail",
   565→        workspaceId,
   566→        agentId: decodeURIComponent(parts[3]),
   567→      };
   568→    }
   569→
   570→    if (parts[2] === "executor" && parts[3]) {
   571→      return {
   572→        kind: "workspace-executor-detail",
   573→        workspaceId,
   574→        executorType: decodeURIComponent(parts[3]),
   575→      };
   576→    }
   577→
   578→    if (parts[2] === "web") {
   579→      return {
   580→        kind: "workspace-web",
   581→        workspaceId,
   582→        url: parsed.searchParams.get("url") ?? "",
   583→        title: parsed.searchParams.get("title") ?? "Web",
   584→        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
   585→        webId: parsed.searchParams.get("web_id") ?? undefined,
   586→      };
   587→    }
   588→
   589→    return {
   590→      kind: "workspace-section",
   591→      workspaceId,
   592→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   593→    };
   594→  }
   595→
   596→  return { kind: "global-route", path: url };
   597→}
